(function()
  local t = {t}
  if t < 0 then t = 0 elseif t > 1 then t = 1 end
  return {a} + ({b} - {a}) * t
end)()

(function()
  local v, th, eps = {value}, {threshold}, {epsilon}
  local mode, outm = '{mode}', '{output_mode}'
  local ok = false
  if mode == 'above' then ok = (v >= th)
  elseif mode == 'below' then ok = (v <= th)
  else ok = (math.abs(v - th) <= eps)
  end
  if outm == 'gate' then return ok and v or 0 end
  if outm == 'invert_binary' then return ok and 0 or 1 end
  return ok and 1 or 0
end)()

(function()
  local v, z = {value}, {zone}
  if z < 0 then z = 0 end
  local a = math.abs(v)
  if a <= z then return 0 end
  if not {soft} then return v end
  local sign = (v >= 0) and 1 or -1
  return sign * (a - z)
end)()

(function()
  local k = {slot}
  local v, a = {value}, {alpha}
  if a < 0.01 then a = 0.01 elseif a > 1 then a = 1 end
  local s = _cs_plugin_smooth
  if s[k] == nil then s[k] = v end
  s[k] = s[k] + (v - s[k]) * a
  return s[k]
end)()
